167	    /**
168	     * The derived identity key used for duplicate detection, formed as
169	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
170	     * The telephone and email are already stored in their normalized forms (E.164 and
171	     * lower-cased), so the key is a straight concatenation of the stored values. Two owners
172	     * are considered the same only when their whole identity keys are equal.
173	     */
174	    @Transient
175	    public String getIdentityKey() {
176	        String tel = this.telephone == null ? "" : this.telephone;
177	        String mail = this.email == null ? "" : this.email;
178	        String household = this.householdId == null ? "" : this.householdId;
179	        return tel + "|" + mail + "|" + household;
180	    }
181	
182	    protected Set<Pet> getPetsInternal() {
