17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    /** Dedicated audit trail logger; carries a line for each successful owner create. */
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
126	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
127	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
128	     *
129	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
130	     *         a valid E.164 number.
131	     */
132	    private static String toE164(String raw) {
133	        if (raw == null) {
134	            return null;
135	        }
136	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
137	        String digits;
138	        if (cleaned.startsWith("+")) {
139	            digits = cleaned.substring(1);
140	        } else {
141	            if (cleaned.startsWith("0")) {
142	                cleaned = cleaned.substring(1);
143	            }
144	            digits = "61" + cleaned;
145	        }
146	        if (!digits.matches("\\d{8,15}")) {
147	            return null;
148	        }
149	        return "+" + digits;
150	    }
151	
152	    /**
153	     * Validate the national-number length of a canonical E.164 string against its country code:
154	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
155	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
156	     * string produced by {@link #toE164}.
157	     *
158	     * @return {@code true} when the national-number length is correct for the country code.
159	     */
160	    private static boolean hasValidNationalLength(String e164) {
161	        String digits = e164.substring(1);
162	        if (digits.startsWith("61")) {
163	            return digits.length() - 2 == 9;
164	        }
165	        if (digits.startsWith("1")) {
166	            return digits.length() - 1 == 10;
167	        }
168	        return true;
169	    }
170	
171	    /**
172	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
173	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
174	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
175	     * (e.g. {@code SYD-SMI-0007}).
176	     */
177	    private String nextCustomerCode(String city, String lastName) {
178	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
179	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
180	        int sequence = 1;
181	        for (Owner existing : this.clinicService.findAllOwners()) {
182	            if (city.equalsIgnoreCase(existing.getCity())) {
183	                sequence++;
184	            }
185	        }
186	        return String.format("%s-%s-%04d", city3, last3, sequence);
187	    }
188	
189	    /** Common street-type abbreviations expanded during address normalization. */
190	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
191	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
192	
193	    /**
194	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
195	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
196	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
197	     */
198	    private static String normalizeAddress(String value) {
199	        if (value == null) {
200	            return "";
201	        }
202	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
203	        if (collapsed.isEmpty()) {
204	            return "";
205	        }
206	        String[] tokens = collapsed.split(" ");
207	        StringBuilder sb = new StringBuilder(collapsed.length());
208	        for (int i = 0; i < tokens.length; i++) {
209	            if (i > 0) {
210	                sb.append(' ');
211	            }
212	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
213	        }
214	        return sb.toString();
215	    }
216	
217	    /**
218	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
219	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
220	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
221	     */
222	    private static String normalizeForHousehold(String value) {
223	        if (value == null) {
224	            return "";
225	        }
226	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
227	    }
228	
229	    /**
230	     * Return the owners that already share this owner's household, i.e. have the same last name and
231	     * address compared case-insensitively with collapsed whitespace.
232	     */
233	    private List<Owner> householdMembers(Owner owner) {
234	        String lastName = normalizeForHousehold(owner.getLastName());
235	        String address = normalizeForHousehold(owner.getAddress());
236	        List<Owner> members = new java.util.ArrayList<>();
237	        for (Owner existing : this.clinicService.findAllOwners()) {
238	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
239	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
240	                members.add(existing);
241	            }
242	        }
243	        return members;
244	    }
245	
246	    /**
247	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
248	     * last name and address compared case-insensitively with collapsed whitespace.
249	     */
250	    private boolean sharesHouseholdWithExisting(Owner owner) {
251	        return !householdMembers(owner).isEmpty();
252	    }
253	
254	    /**
255	     * Count the existing owners that share this owner's first name and last name, compared
256	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
257	     */
258	    private int namesakeCount(Owner owner) {
259	        String firstName = owner.getFirstName();
260	        String lastName = owner.getLastName();
261	        int count = 0;
262	        for (Owner existing : this.clinicService.findAllOwners()) {
263	            if (firstName != null && lastName != null
264	                && firstName.equalsIgnoreCase(existing.getFirstName())
265	                && lastName.equalsIgnoreCase(existing.getLastName())) {
266	                count++;
267	            }
268	        }
269	        return count;
270	    }
271	
272	    /**
273	     * A stable, shared household identifier derived from the normalized last name and address, so every
274	     * owner in the same household deterministically resolves to the same value.
275	     */
276	    private static String householdIdFor(Owner owner) {
277	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
278	        try {
279	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
280	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
281	            StringBuilder sb = new StringBuilder(24);
282	            for (int i = 0; i < 12; i++) {
283	                sb.append(String.format("%02X", digest[i]));
284	            }
285	            return sb.toString();
286	        }
287	        catch (java.security.NoSuchAlgorithmException e) {
288	            throw new IllegalStateException(e);
289	        }
290	    }
291	
292	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
293	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
294	        "NSW", new int[] {2000, 2099},
295	        "VIC", new int[] {3000, 3099},
296	        "QLD", new int[] {4000, 4099});
297	
298	    /**
299	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
300	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
301	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
302	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
303	     * postcode.
304	     */
305	    private boolean isPostcodeValid(Owner owner) {
306	        String postcode = owner.getPostcode();
307	        if (postcode == null || postcode.isEmpty()) {
308	            return true;
309	        }
310	        if (!postcode.matches("\\d{4}")) {
311	            return false;
312	        }
313	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
314	        if (range == null) {
315	            return true;
316	        }
317	        int value = Integer.parseInt(postcode);
318	        return value >= range[0] && value <= range[1];
319	    }
320	
321	    /** Maximum number of owners permitted in a single city. */
322	    private static final int CITY_CAPACITY = 50;
323	
324	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
325	    private static final int DAILY_CREATE_LIMIT = 100;
326	
327	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
328	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
329	
330	    /**
331	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
332	     * Used to enforce the per-city capacity on create (before this owner is saved).
333	     */
334	    private int cityOwnerCount(Owner owner) {
335	        String city = owner.getCity();
336	        int count = 0;
337	        for (Owner existing : this.clinicService.findAllOwners()) {
338	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
339	                count++;
340	            }
341	        }
342	        return count;
343	    }
344	
345	    /**
346	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
347	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
348	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
349	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
350	     */
351	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
352	        switch (date.getDayOfWeek()) {
353	            case SATURDAY:
354	                return date.plusDays(2);
355	            case SUNDAY:
356	                return date.plusDays(1);
357	            default:
358	                return date;
359	        }
360	    }
361	
362	    /**
363	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
364	     * per-day create limit on create (before this owner is saved).
365	     */
366	    private int ownersRegisteredOn(java.time.LocalDate day) {
367	        int count = 0;
368	        for (Owner existing : this.clinicService.findAllOwners()) {
369	            if (day.equals(existing.getRegistrationDate())) {
370	                count++;
371	            }
372	        }
373	        return count;
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
379	        HttpHeaders headers = new HttpHeaders();
380	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
381	        if (!isPostcodeValid(owner)) {
382	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
383	        }
384	        String telephone = toE164(owner.getTelephone());
385	        if (telephone == null || !hasValidNationalLength(telephone)) {
386	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
387	        }
388	        if (!normalizeEmail(owner)) {
389	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
390	        }
391	        String address = normalizeAddress(owner.getAddress());
392	        if (address.isEmpty()) {
393	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
394	        }
395	        owner.setAddress(address);
396	        owner.setTelephone(telephone);
397	        java.time.LocalDate registrationDate = toBusinessDay(
398	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
399	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
400	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
401	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
402	        }
403	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
404	            return new ResponseEntity<>(HttpStatus.CONFLICT);
405	        }
406	        List<Owner> householdMembers = householdMembers(owner);
407	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
408	        if (sharesHousehold && !householdMembers.isEmpty()) {
409	            owner.setHouseholdId(householdMembers.stream()
410	                .map(Owner::getHouseholdId)
411	                .filter(id -> id != null && !id.isBlank())
412	                .findFirst()
413	                .orElseGet(() -> householdIdFor(owner)));
414	        }
415	        // Consolidated duplicate detection: the former separate telephone, email and household
416	        // checks are now all expressed through the single derived identityKey, so a new owner is
417	        // rejected only when its WHOLE identityKey equals an existing owner's. Because the telephone
418	        // is part of the key, two members of the same household with different telephones have
419	        // different identityKeys and are both allowed.
420	        String identityKey = owner.getIdentityKey();
421	        for (Owner existing : this.clinicService.findAllOwners()) {
422	            if (identityKey.equals(existing.getIdentityKey())) {
423	                return new ResponseEntity<>(HttpStatus.CONFLICT);
424	            }
425	        }
426	        if (owner.getHouseholdId() != null) {
427	            for (Owner member : householdMembers) {
428	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
429	                    member.setHouseholdId(owner.getHouseholdId());
430	                    this.clinicService.saveOwner(member);
431	                }
432	            }
433	        }
434	        owner.setNamesakeCount(namesakeCount(owner));
435	        owner.setHouseholdSize(householdMembers.size() + 1);
436	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
437	        owner.setRegistrationDate(registrationDate);
438	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
439	        this.clinicService.saveOwner(owner);
440	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
441	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
442	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
443	        headers.setLocation(UriComponentsBuilder.newInstance()
444	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
445	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
451	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
452	        if (currentOwner == null) {
453	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	        }
455	        currentOwner.setAddress(ownerFieldsDto.getAddress());
456	        currentOwner.setCity(ownerFieldsDto.getCity());
457	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
458	        currentOwner.setLastName(ownerFieldsDto.getLastName());
459	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
460	        currentOwner.setEmail(ownerFieldsDto.getEmail());
461	        if (!normalizeEmail(currentOwner)) {
462	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
463	        }
464	        this.clinicService.saveOwner(currentOwner);
465	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
466	    }
467	
468	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
469	    @Transactional
470	    @Override
471	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
472	        Owner owner = this.clinicService.findOwnerById(ownerId);
473	        if (owner == null) {
474	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
475	        }
476	        this.clinicService.deleteOwner(owner);
477	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
478	    }
479	
480	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
481	    @Override
482	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
483	        Owner owner = this.clinicService.findOwnerById(ownerId);
484	        if (owner == null) {
485	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	        }
487	        HttpHeaders headers = new HttpHeaders();
488	        Pet pet = petMapper.toPet(petFieldsDto);
489	        owner.setId(ownerId);
490	        pet.setOwner(owner);
491	        pet.getType().setName(null);
492	        this.clinicService.savePet(pet);
493	        PetDto petDto = petMapper.toPetDto(pet);
494	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
495	            .buildAndExpand(pet.getId()).toUri());
496	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
502	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
503	        if (currentOwner != null) {
504	            Pet currentPet = this.clinicService.findPetById(petId);
505	            if (currentPet != null) {
506	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
507	                currentPet.setName(petFieldsDto.getName());
508	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
509	                this.clinicService.savePet(currentPet);
510	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
511	            }
512	        }
513	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
514	    }
515	
516	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
517	    @Override
518	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
519	        HttpHeaders headers = new HttpHeaders();
520	        Visit visit = visitMapper.toVisit(visitFieldsDto);
521	        Pet pet = new Pet();
522	        pet.setId(petId);
523	        visit.setPet(pet);
524	        this.clinicService.saveVisit(visit);
525	        VisitDto visitDto = visitMapper.toVisitDto(visit);
526	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
527	            .buildAndExpand(visit.getId()).toUri());
528	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
529	    }
530	
531	
532	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
533	    @Override
534	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
535	        Owner owner = this.clinicService.findOwnerById(ownerId);
536	        if (owner != null) {
537	            Pet pet = owner.getPet(petId);
538	            if (pet != null) {
539	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
540	            }
541	        }
542	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
543	    }
544	}
